def parse_count(text):
    # Intended grammar: one digit, colon, exactly that many letters
    n = int(text[0])       # empty input unexpectedly raises IndexError
    if text[1] != ":": raise ValueError("separator")
    body=text[2:]
    if len(body)!=n or not body.isalpha(): raise ValueError("body")
    return body

